1: :root{color-scheme:dark;--gold:#c7a568;--pale:#e8d9b7;--muted:#a79c83;--line:rgba(199,165,104,.3);--ink:#12130f;--display:'Cinzel',serif;--body:'Lora',serif}
2: *{box-sizing:border-box}
3: html,body{width:100%;height:100%;margin:0;overflow:hidden}
4: body{background:#121711;color:var(--pale);font-family:var(--body)}
5: button{font:inherit}
6: #game{position:fixed;inset:0;width:100%;height:100%;display:block;outline:none}
7: .world-treatment{position:fixed;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,10,8,.64),transparent 22%,transparent 60%,rgba(8,10,8,.62)),radial-gradient(ellipse at center,transparent 35%,rgba(5,7,5,.3) 100%);z-index:1}
8: .hud{position:fixed;inset:0;z-index:2;pointer-events:none}
9: .topbar{position:absolute;top:0;left:0;right:0;height:94px;display:flex;align-items:flex-start;padding:28px 42px;gap:80px}
10: .brand{display:flex;align-items:center;gap:11px;font:600 16px/1 var(--display);letter-spacing:.13em;color:#e8ddc1;white-space:nowrap}
11: .brand em{font-style:normal;color:var(--gold)}
12: .brand small,.location-wrap small{display:block;font:600 8px/1.5 var(--display);letter-spacing:.2em;color:#b1a384;margin-top:6px}
13: .brand-mark{font-size:25px;color:var(--gold);font-weight:400}
14: .location-wrap{display:flex;gap:11px;align-items:center;border-left:1px solid var(--line);padding-left:30px;margin-top:1px}
